local a=require"system.hardware"local b=require"system.util"local c={...}if c[1]=="probe"then local d=false;print("Redstone inputs:")local e={}for f,g in ipairs(a.children("/redstone"))do local h=a.wrap("/redstone/"..g)local i=h.bundledInput;if i and i>0 then d=true end;local j=h.input;if j then e[#e+1]=g.." ("..j..")"end end;if#e>0 then print(table.concat(e,", "))else print("None.")end;if d then print()print("Bundled inputs:")local k={[0]="white","orange","magenta","lightBlue","yellow","lime","pink","gray","lightGray","cyan","purple","blue","brown","green","red","black"}for f,g in ipairs(a.children("/redstone"))do local h=a.wrap("/redstone/"..g)local i=h.bundledInput;if i and i>0 then io.write(g..": ")local e={}for l=0,15 do if bit32.btest(i,2^l)then e[#e+1]=k[l]end end;print(table.concat(e,", "))end end end elseif c[1]=="set"then if#c<3 then error("Usage: redstone set <side> [color] <value>")end;local h=assert(a.wrap("/redstone/"..c[2]),"Not a side")if#c>=4 then if not h.bundledOutput then error("Bundled output is not available")end;local k={white=0,orange=1,magenta=2,lightBlue=3,yellow=4,lime=5,pink=6,gray=7,grey=7,lightGray=8,lightGrey=8,cyan=9,purple=10,blue=11,brown=12,green=13,red=14,black=15}local m=2^assert(k[c[3]],"Invalid color")if c[4]:lower()=="true"then h.bundledOutput=bit32.bor(h.bundledOutput,m)else h.bundledOutput=bit32.band(h.bundledOutput,bit32.bnot(m))end else local n;if c[3]:lower()=="true"then n=15 else n=tonumber(c[3])or 0 end;h.output=n end elseif c[1]=="pulse"then if#c<4 then error("Usage: redstone pulse <side> <count> <period>")end;local h=assert(a.wrap("/redstone/"..c[2]),"Not a side")local o=tonumber(c[3])or 1;local p=tonumber(c[4])or 0.5;for f=1,o do h.output=true;b.sleep(p/2)h.output=false;b.sleep(p/2)end else print("Usage: redstone <probe|set|pulse> ...")end
